contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint deposit) public payable {
        require(deposit > 0);
        require(address(this).balance >= deposit);

        // Deposit Ether into c to create a positive recorded balance for this contract.
        (bool depositOk, ) = address(c).call{value: deposit}("");
        require(depositOk, "deposit failed");

        uint256 balBefore = address(this).balance;

        // Deciding call: withdraw everything recorded for this contract.
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If withdraw succeeded, the recorded balance must be zero and
        // the test contract must have received at least the deposited amount.
        assert(reverted || (c.balances(address(this)) == 0 && address(this).balance >= balBefore + deposit));
    }

    receive() external payable {}
}

