    constructor(C _c) {
        c = _c;
    }

    function run(address other, uint amount) public payable {
        require(other != address(this), "other must differ from test contract");
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "insufficient balance");

        (bool ok, ) = address(c).call{value: amount}("");
        require(ok, "deposit failed");

        uint256 callerBefore = c.balances(address(this));
        uint256 otherBefore = c.balances(other);
        uint256 cBefore = address(c).balance;

        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 callerAfter = c.balances(address(this));
        uint256 otherAfter = c.balances(other);
        uint256 cAfter = address(c).balance;

        assert(
            reverted ||
            (callerAfter == 0 &&
             otherAfter == otherBefore &&
             cBefore >= callerBefore &&
             cAfter == cBefore - callerBefore)
        );
    }

    receive() external payable {}
}

