    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(uint256 depositAmount) public payable {
        require(depositAmount > 0, "deposit must be positive");
        require(address(this).balance >= depositAmount, "insufficient test balance");

        // fund this test contract and deposit into c via fallback
        (bool ok, ) = address(c).call{value: depositAmount}("");
        require(ok, "deposit into c failed");

        uint256 priorBalance = c.balances(address(this));
        require(priorBalance == depositAmount, "unexpected prior balance");

        uint256 cBalBefore = address(c).balance;

        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }

        uint256 cBalAfter = address(c).balance;
        uint256 balanceAfter = c.balances(address(this));

        assert(!reverted && balanceAfter == 0 && cBalAfter == cBalBefore - priorBalance);
    }
}

