contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, uint deposit, uint withdrawAmount) public payable {
        require(caller != address(0));
        require(deposit > 0);
        require(withdrawAmount > 0);
        require(address(this).balance >= deposit);

        // Set up: caller deposits via fallback, credited to caller in c's balances mapping
        (bool dOk, ) = caller.call{value: deposit}(abi.encodeWithSignature("deposit()"));
        require(dOk);

        // Read before-state
        uint256 beforeCaller = c.balances(caller);
        uint256 beforeC = address(c).balance;

        // Deciding call: drive c.withdraw() as caller via a low-level call so we can capture revert
        (bool ok, ) = caller.call(abi.encodeWithSignature("withdraw()"));

        // Read after-state
        uint256 afterCaller = c.balances(caller);
        uint256 afterC = address(c).balance;

        // Rule: withdraw succeeds iff c has at least the caller's recorded balance to send
        //       (and the caller's fallback/receive accepts it); on success the caller's
        //       balance is zeroed and c's Ether reserve decreases by exactly that balance.
        if (ok) {
            assert(afterCaller == 0);
            assert(beforeC >= afterC);
            assert(beforeC - afterC == beforeCaller);
        } else {
            // On revert, c's Ether balance is unchanged and the caller's balance is unchanged
            assert(afterC == beforeC);
            assert(afterCaller == beforeCaller);
        }
    }

    receive() external payable {}
}

