contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address recipient, uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount, "not enough balance");

        // Ensure the recipient has a positive balance in c so withdraw() attempts a transfer.
        c.balances{value: depositAmount}(recipient);

        uint256 beforeRecipientBalance = c.balances(recipient);
        uint256 beforeContractBalance = address(c).balance;

        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.balances(recipient) == 0);
            assert(address(c).balance == beforeContractBalance - beforeRecipientBalance);
        } else {
            assert(c.balances(recipient) == beforeRecipientBalance);
            assert(address(c).balance == beforeContractBalance);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address recipient, uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount, "not enough balance");
        require(depositAmount > 0, "zero deposit");

        // Deposit Ether into c under the recipient's address, giving them a positive recorded balance.
        (bool depositOk, ) = address(c).call{value: depositAmount}("");
        require(depositOk, "deposit failed");

        // Read the before-state.
        uint256 beforeRecipientBalance = c.balances(recipient);
        uint256 beforeContractBalance = address(c).balance;

        // The deciding call: attempt withdraw from the recipient.
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: withdraw succeeds iff transferring the recipient's recorded balance succeeds.
        // Since the recipient balance equals depositAmount (positive), the only reason a transfer
        // could fail is if c's Ether reserve cannot cover it, i.e. address(c).balance < depositAmount.
        assert(reverted == (beforeContractBalance < beforeRecipientBalance));

        if (!reverted) {
            assert(c.balances(recipient) == 0);
            assert(address(c).balance == beforeContractBalance - beforeRecipientBalance);
        } else {
            assert(c.balances(recipient) == beforeRecipientBalance);
            assert(address(c).balance == beforeContractBalance);
        }
    }
}

