        assert(reverted == (beforeContractBalance < callerBalance));
        if (!reverted) {
            assert(callerBalance == 0);
            assert(address(c).balance == beforeContractBalance - callerBalance == 0 ? beforeContractBalance : beforeContractBalance - callerBalance);
        } else {
            assert(callerBalance == 0);
            assert(address(c).balance == beforeContractBalance);
        }
    }

    receive() external payable {}
}

