    constructor(C _c) {
        c = _c;
    }

    function run(address a) public payable {
        require(a != address(0));

        uint256 balBefore = c.balances(a);
        uint256 cEthBefore = address(c).balance;

        require(balBefore == 0);

        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = c.balances(a);
        uint256 cEthAfter = address(c).balance;

        assert(!reverted && balAfter == 0 && cEthAfter == cEthBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address other) public payable {
        require(caller != address(this));
        require(other != caller);
        require(msg.value >= 0);

        bool depositReverted;
        try c.withdraw() { depositReverted = false; } catch { depositReverted = true; }
        require(!depositReverted);

        uint256 amount = c.balances(caller);
        uint256 reserveBefore = address(c).balance;
        uint256 otherBefore = c.balances(other);

        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }

        if (!reverted && amount > 0) {
            assert(c.balances(caller) == 0 && address(c).balance == reserveBefore - amount && c.balances(other) == otherBefore);
        } else {
            assert(c.balances(caller) == amount && address(c).balance == reserveBefore && c.balances(other) == otherBefore);
        }
    }

    receive() external payable {}
}

